using System;using System.IO;using System.Diagnostics;using System.Collections.Generic;
public static class HousekeepingRegression {
 static void Check(bool ok,string reason){if(!ok)throw new Exception(reason);}
 static void Manifest(string dir,string install,string version,string content){Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"component.txt"),content);HostCore.Save(Path.Combine(dir,".ygpt-install.json"),new{product="YGPT Local",version=version,installRoot=install});HostCore.Save(Path.Combine(dir,"manifest.json"),new{product="YGPT Local",version=version,files=new[]{new{path="component.txt",sha256=HostCore.Hash(Path.Combine(dir,"component.txt"))}}});}
 static string Backup(string install,string transaction,string version,int minutes){string p=Path.Combine(install,".updates",transaction,"previous");Manifest(p,install,version,"old payload "+version);Directory.SetCreationTimeUtc(p,DateTime.UtcNow.AddMinutes(minutes));return p;}
 static void Health(string install,string data,bool ready){var p=Process.GetCurrentProcess();HostCore.Save(Path.Combine(data,"watchdog-health.json"),new{ownerId=HostCore.OwnerId(data),installRoot=install,version="fixture",localReady=ready,tunnelConnected=false,pid=p.Id,birth=p.StartTime.ToUniversalTime().Ticks,at=DateTime.UtcNow.ToString("o"),stopped=false});}
 public static int Main(string[] args){string root=args[0],install=Path.Combine(root,"application"),data=Path.Combine(install,"data");Directory.CreateDirectory(data);
  if(args[1]=="legacy-download"){
   HostCore.SaveSecrets(data,new Dictionary<string,object>{{"verificationKey",new string('k',64)}});string file=Path.Combine(root,"old-installer.exe");File.WriteAllText(file,"preserve exact legacy download");var current=Process.GetCurrentProcess();
   InstallCleanup.Record(data,Path.Combine(root,"old-install"),"legacy",new[]{InstallCleanup.Entry(file,"legacy","setup-download",root,true)},true,current.Id,current.StartTime.ToUniversalTime().Ticks);
   var review=InstallCleanup.Run(data,install);Check((string)review["state"]=="review-required"&&(string)review["code"]=="INSTALLATION_SCOPE_CHANGED","Legacy scope must produce a clear review receipt");Check(File.ReadAllText(file)=="preserve exact legacy download","Old consent must not be rebound to the current scope");Check(!InstallCleanup.Due(data),"An unchanged legacy receipt must not repeatedly block maintenance");
   InstallCleanup.Record(data,install,"current",new[]{InstallCleanup.Entry(file,"current","update-download",root,true)},true,current.Id,current.StartTime.ToUniversalTime().Ticks);Check(InstallCleanup.Due(data),"Registering a current updater must resume download cleanup");Console.WriteLine("LEGACY_DOWNLOAD_SCOPE_PASS");return 0;
  }
  if(args[1]=="registration"){
   string missing=Path.Combine(root,"missing-data"),key="YGPTLocal-"+HostCore.OwnerId(missing).Substring(0,12),command=HostCore.Q(Path.Combine(install,"YGPTLocal.exe"))+" --uninstall --data-dir "+HostCore.Q(missing);
   Check(InstallationHousekeeping.RegistrationReason(key,"YGPT Local",install,command,install,data)!=null,"Obsolete same-install data alias should be eligible");
   string currentKey="YGPTLocal-"+HostCore.OwnerId(data).Substring(0,12),current=HostCore.Q(Path.Combine(install,"YGPTLocal.exe"))+" --uninstall --data-dir "+HostCore.Q(data);
   Check(InstallationHousekeeping.RegistrationReason(currentKey,"YGPT Local",install,current,install,data)==null,"Current registration must remain");Check(InstallationHousekeeping.RegistrationReason(key,"Other product",install,command,install,data)==null,"Foreign product must remain");Check(InstallationHousekeeping.RegistrationReason("YGPTLocal-000000000000","YGPT Local",install,command,install,data)==null,"Path identity must match key");Check(InstallationHousekeeping.RegistrationReason(key,"YGPT Local",install,command+" --unexpected",install,data)==null,"Unrecognized command must remain");
   string live=Path.Combine(root,"other-install"),liveData=Path.Combine(live,"data");Directory.CreateDirectory(liveData);Check(InstallationHousekeeping.RegistrationReason("YGPTLocal-"+HostCore.OwnerId(liveData).Substring(0,12),"YGPT Local",live,HostCore.Q(Path.Combine(live,"YGPTLocal.exe"))+" --uninstall --data-dir "+HostCore.Q(liveData),install,data)==null,"Another installation must remain");
   HostCore.Save(Path.Combine(data,"installation-ownership.json"),new{authorized=true,manifestMac="first"});HostCore.Save(Path.Combine(data,"post-install-cleanup-receipt.json"),new{state="complete",ownershipMac="first",at=DateTime.UtcNow.ToString("o")});Check(!InstallCleanup.Due(data),"Completed same download manifest should not repeat");HostCore.Save(Path.Combine(data,"installation-ownership.json"),new{authorized=true,manifestMac="next-update"});Check(InstallCleanup.Due(data),"An old Complete receipt must not suppress a newly registered updater");Console.WriteLine("REGISTRATION_AND_DOWNLOAD_PASS");return 0;
  }
  Manifest(install,install,"fixture","current payload");HostCore.Save(Path.Combine(data,"connection.json"),new{mode="local-only"});File.WriteAllText(Path.Combine(data,"private.txt"),"keep private");Directory.CreateDirectory(Path.Combine(data,"state","backups","snapshot"));File.WriteAllText(Path.Combine(data,"state","backups","snapshot","keep.txt"),"keep snapshot");
  string old=Backup(install,new string('a',32),"old-a",-30),middle=Backup(install,new string('b',32),"old-b",-20),latest=Backup(install,new string('c',32),"latest",-10),unknown=Backup(install,new string('d',32),"changed",-5);File.WriteAllText(Path.Combine(unknown,"component.txt"),"owner modification");
  string release=Path.Combine(install,".updates","releases","0.9.0");Directory.CreateDirectory(release);string download=Path.Combine(release,"YGPTLocal-Update-0.9.0-win-x64.exe");File.WriteAllText(download,"download fixture");File.WriteAllText(Path.Combine(release,"SHA256SUMS.txt"),HostCore.Hash(download)+"  "+Path.GetFileName(download)+"\n");
  Health(install,data,false);var deferred=InstallationHousekeeping.Run(install,data,true,false);Check((string)deferred["state"]=="deferred"&&Directory.Exists(old)&&File.Exists(download),"No cache deletion before health verification");
  Health(install,data,true);var result=InstallationHousekeeping.Run(install,data,true,false);Check(Convert.ToInt32(result["removedRollbackCopies"])==2,"Remove surplus verified copies");Check(!Directory.Exists(old)&&!Directory.Exists(middle)&&Directory.Exists(latest),"Retain exactly the latest valid rollback");Check(Directory.Exists(unknown)&&File.ReadAllText(Path.Combine(unknown,"component.txt"))=="owner modification","Changed cache is not automatically deleted");Check(!File.Exists(download),"Verified contained installer cache should be removed");Check(File.ReadAllText(Path.Combine(install,"component.txt"))=="current payload"&&File.ReadAllText(Path.Combine(data,"private.txt"))=="keep private"&&File.Exists(Path.Combine(data,"state","backups","snapshot","keep.txt")),"Current runtime and private snapshots must remain");Check(HostCore.B(result,"reviewRequired"),"Retained changed files need explicit review feedback");
  File.WriteAllText(Path.Combine(latest,"component.txt"),"now changed");Directory.CreateDirectory(release);File.WriteAllText(download,"fallback repair installer");File.WriteAllText(Path.Combine(release,"SHA256SUMS.txt"),HostCore.Hash(download)+"  "+Path.GetFileName(download)+"\n");Health(install,data,true);InstallationHousekeeping.Run(install,data,true,false);Check(File.Exists(download),"Retain repair installer when no rollback passes verification");Console.WriteLine("HOUSEKEEPING_PASS");return 0;
 }
}
